from taf.internal.core import Factory
from taf.internal.execution.base import ExecutorFactory
from taf.internal.execution.k8s import K8sExecutor


class K8sExecutorFactory(Factory):
    _mandatory_parameters = {"namespace", "container"}
    _optional_parameters = {"pod", "sudo_password"}
    _product_class = K8sExecutor

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(K8sExecutorFactory, self)._build_arguments(configuration, existing_arguments, resulting_arguments)
        resulting_arguments["tool_executor"] = ExecutorFactory().create(
            configuration=configuration["executor"],
            existing_arguments=existing_arguments)
